LoadingCache<Integer, Integer> cache = Caffeine.newBuilder()
    .maximumSize(100)
    .refreshAfterWrite(Duration.ofMillis(150))
    .removalListener((key, value, cause) ->
        System.out.println(key + " usuniety: " + cause))
    .build(key -> expensiveSquare(key));

int result = cache.get(7); // auto-oblicza i zapamietuje

AsyncLoadingCache<Integer, String> asyncCache = Caffeine.newBuilder()
    .buildAsync(key -> {
        Thread.sleep(40);
        return "produkt-" + key;
    });
CompletableFuture<String> future = asyncCache.get(5); // NIE blokuje
String value = future.thenApply(String::toUpperCase).join();
